"""Independent re-implementation used only as a cross-check in testing."""
import ipaddress

def labels(n):
    return [] if n == '.' else n[:-1].split('.')

def nlabs(n):
    return len(labels(n))

def parent(n):
    l = labels(n)
    return '.' if len(l) <= 1 else '.'.join(l[1:]) + '.'

def anc_chain(n):
    out = []
    while True:
        out.append(n)
        if n == '.': break
        n = parent(n)
    return out

def build(zones_raw):
    zs = []
    for z in zones_raw:
        origin = z['origin'].lower()
        rr = {}
        for r in z['records']:
            o = r['owner'].lower(); t = r['type']; d = r['data']
            if t == 'AAAA': d = ipaddress.IPv6Address(d).compressed
            rr.setdefault(o, {}).setdefault(t, set()).add(d)
        exist = set([origin])
        for o in rr:
            for a in anc_chain(o):
                if nlabs(a) >= nlabs(origin):
                    exist.add(a)
        zs.append({'origin': origin, 'rr': {o: {t: sorted(ds) for t, ds in ts.items()} for o, ts in rr.items()},
                   'exist': exist})
    return zs

def pick_zone(zs, name):
    best = None
    for z in zs:
        o = z['origin']
        if o == '.' or name == o or name.endswith('.' + o):
            if best is None or nlabs(o) > nlabs(best['origin']):
                best = z
    return best

def resolve(zs, qname, qtype, prof):
    cur = qname; seen = []; followed = 0; ans = []; trace = []
    while True:
        trace.append(cur)
        if cur in seen:
            return ('SERVFAIL', 'LOOP', cur, ans, trace)
        seen.append(cur)
        z = pick_zone(zs, cur)
        if z is None:
            return ('REFUSED', 'OUTSIDE', cur, ans, trace) if followed == 0 else ('NOERROR', 'EXTERNAL', cur, ans, trace)
        src = None
        if cur in z['exist']:
            src = cur
        elif prof['wildcard'] != 'off':
            cands = [a for a in anc_chain(cur)[1:] if a in z['exist']]
            if cands:
                enc = max(cands, key=nlabs)
                src = '*.' if enc == '.' else '*.' + enc
                if src not in z['exist']:
                    src = None
                elif prof['wildcard'] == 'one-label' and nlabs(cur) != nlabs(enc) + 1:
                    src = None
        if src is None:
            return ('NXDOMAIN', 'NXDOMAIN', cur, ans, trace)
        at = z['rr'].get(src, {})
        cn = at.get('CNAME', [])
        if qtype == 'CNAME':
            if cn:
                ans.append((cur, 'CNAME', cn[0]))
                return ('NOERROR', 'ANSWER', cur, ans, trace)
            return ('NOERROR', 'NODATA', cur, ans, trace)
        if cn:
            if prof['cname'] == 'stop':
                ans.append((cur, 'CNAME', cn[0]))
                return ('NOERROR', 'CNAME_STOP', cur, ans, trace)
            if followed == prof['max_aliases']:
                return ('SERVFAIL', 'LIMIT', cur, ans, trace)
            ans.append((cur, 'CNAME', cn[0]))
            followed += 1
            cur = cn[0]
            continue
        want = at.get(qtype, [])
        if want:
            for d in sorted(set(want)):
                ans.append((cur, qtype, d))
            return ('NOERROR', 'ANSWER', cur, ans, trace)
        return ('NOERROR', 'NODATA', cur, ans, trace)

def basis_bruteforce(profiles, queries, proj):
    """Exhaustive optimum over all subsets (small query counts only)."""
    pids = sorted(p['id'] for p in profiles)
    qids = sorted(q['id'] for q in queries)
    pairs = [(a, b) for i, a in enumerate(pids) for b in pids[i+1:]
             if any(proj[(q, a)] != proj[(q, b)] for q in qids)]
    best = None
    n = len(qids)
    for mask in range(1 << n):
        sel = [qids[i] for i in range(n) if mask >> i & 1]
        cost = sum(q['cost'] for q in queries if q['id'] in sel)
        cand = (cost, len(sel), sorted(sel))
        if all(any(proj[(q, a)] != proj[(q, b)] for q in sel) for a, b in pairs):
            if best is None or cand[:2] < best[:2]:
                best = cand
    # equivalence classes
    groups = {}
    for p in pids:
        key = tuple(proj[(q, p)] for q in qids)
        groups.setdefault(key, []).append(p)
    equiv = sorted(sorted(v) for v in groups.values())
    if best is None:
        best = (0, 0, [])
    return equiv, best[2], best[0], best[1]
